{
  "findings": [
    {
      "check_id": "CKV2_AZURE_31",
      "title": "Ensure VNET subnet is configured with a Network Security Group (NSG)",
      "resource": "azurerm_subnet.data_subnet",
      "severity": "MEDIUM",
      "explanation": "The azurerm_subnet resource does not have an associated network_security_group_id, leaving the subnet without explicit inbound/outbound traffic filtering rules."
    }
  ],
  "patched_code": "resource \"azurerm_subnet\" \"data_subnet\" {\n  name                      = \"healthcare-patient-portal-with-hipaa-compliance-subnet-data\"\n  resource_group_name       = azurerm_resource_group.healthcare_portal.name\n  virtual_network_name      = azurerm_virtual_network.healthcare_vnet.name\n  address_prefixes          = [\"10.0.3.0/24\"]\n  network_security_group_id = azurerm_network_security_group.example.id\n}\n",
  "fix_summary": "Added the 'network_security_group_id' attribute to the azurerm_subnet resource to associate it with a Network Security Group, ensuring traffic filtering is applied as per CKV2_AZURE_31."
}
